def transform(grid):
    g = [row[:] for row in grid]
    R, C = len(g), len(g[0])
    # Find maximal horizontal and vertical runs of 5s, then extend an adjacent
    # nonzero template along the run's direction.
    horizontal = []
    vertical = []
    for r in range(R):
        c = 0
        while c < C:
            if g[r][c] == 5 and (c == 0 or g[r][c-1] != 5):
                e = c
                while e+1 < C and g[r][e+1] == 5: e += 1
                if e > c: horizontal.append((r,c,e))
                c = e+1
            else: c += 1
    for c in range(C):
        r = 0
        while r < R:
            if g[r][c] == 5 and (r == 0 or g[r-1][c] != 5):
                e = r
                while e+1 < R and g[e+1][c] == 5: e += 1
                if e > r: vertical.append((c,r,e))
                r = e+1
            else: r += 1

    for r,c0,c1 in horizontal:
        # The perpendicular seed is a vertical run immediately beyond either end.
        best = None
        for col in (c0,c1):
            for dr in (-1,1):
                rr = r+dr
                if 0 <= rr < R and g[rr][col] not in (0,5):
                    vals=[]; coords=[]
                    while 0 <= rr < R and g[rr][col] not in (0,5):
                        vals.append(g[rr][col]); coords.append(rr); rr += dr
                    if best is None or len(vals)>len(best[0]): best=(vals,coords)
        if best:
            vals, coords=best
            for cc in range(c0,c1+1):
                for rr,v in zip(coords,vals):
                    if g[rr][cc] == 0: g[rr][cc]=v

    for c,r0,r1 in vertical:
        # A seed panel touches one side of the line; tile its row pattern along it.
        best = None
        for side in (-1,1):
            sc=c+side
            if not 0 <= sc < C: continue
            # Find contiguous runs of nonzero cells alongside the line.
            rr=r0
            while rr<=r1:
                if g[rr][sc] not in (0,5):
                    a=rr
                    while rr+1<=r1 and g[rr+1][sc] not in (0,5): rr+=1
                    b=rr
                    # Pattern rows are copied over the full adjacent width.
                    edge = sc
                    cc=edge
                    while 0<=cc<C and g[a][cc] not in (0,5): cc+=side
                    # collect from adjacent side outwards, preserving coordinate order
                    cols=[]; cc=sc
                    while 0<=cc<C and g[a][cc] not in (0,5):
                        cols.append(cc); cc+=side
                    # Require all rows in panel have the same width of nonzero data.
                    width=len(cols)
                    if width and all(g[pr][pc] not in (0,5) for pr in range(a,b+1) for pc in cols):
                        panel=[[g[pr][pc] for pc in cols] for pr in range(a,b+1)]
                        cand=(panel,a,cols)
                        if best is None or len(panel)>len(best[0]): best=cand
                rr+=1
        if best:
            panel, anchor, cols=best
            h=len(panel)
            # Repeat the panel with phase fixed by its original row coordinates.
            for rr in range(r0,r1+1):
                src=(rr-anchor)%h
                for j,cc in enumerate(cols):
                    if g[rr][cc] == 0: g[rr][cc]=panel[src][j]
    return g
